    $dbr->delete(
        'your_table_name',
        [
            'created_at < ' . $dbr->quote($cutoffTimestamp),
            'afl_ip != ""',
            'afl_ip_hex != ""'
        ],
        __METHOD__
    );

    $dbw = wfGetDB(DB_MASTER);
    $dbw->delete(
        'your_table_name',
        [
            'created_at < ' . $dbw->quote($cutoffTimestamp),
            'afl_ip != ""',
            'afl_ip_hex != ""'
