/**
 * Generator of union of iterables.
 *
 * @param iterable[] $iterables Array of iterables to union.
 * @return Generator Returns a generator that yields elements from all iterables in the union.
 */
function unionIterables(array $iterables): Generator {
    foreach ($iterables as $iterable) {
        foreach ($iterable as $item) {
            yield $item;
        }
    }
