// This endpoint is still experimental and may change in the future.
const timeout = 30000; // Default timeout of 30 seconds
let currentRequest = null;

const execute = async (doc) => {
    if (currentRequest) {
        currentRequest.abort();
    }

    currentRequest = rest.post('/v1/transform/wikitext/to/lint', {
        wikitext: doc.toString()
    }, {
        timeout: timeout
    }).catch(error => {
        mw.log.warn('[CodeMirror] Error during linting: ', error);
        return null;
    });

    try {
        const errors = await currentRequest;
        currentRequest = null;
        return errors;
    } catch (error) {
        currentRequest = null;
        throw error;
    }
};
